    """
    This function implements the Bellman-Ford algorithm to find the shortest path in a weighted directed graph.
    It can handle graphs with negative weights and returns the shortest distance and the path from the start node to the end node.
    """
    vertices = list(graph.keys())
    distances = {vertex: float('inf') for vertex in vertices}
    predecessors = {vertex: None for vertex in vertices}
    distances[start] = 0

    for _ in range(len(vertices) - 1):
        for u in vertices:
            for v, weight in graph[u]:
                if distances[u] != float('inf') and distances[u] + weight < distances[v]:
                    distances[v] = distances[u] + weight
                    predecessors[v] = u

    # Check for negative-weight cycles
    for u in vertices:
        for v, weight in graph[u]:
